&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW240184038 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;The investigation is ongoing, and further inquiries should be directed to the Marion County District Attorney's Office.&lt;/span&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

