&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;Hisako was reported missing in the 5000 block of Gaffin Road SE by her family after they discovered she had not returned from an early morning walk.&lt;/span&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;Officers canvassed the area, and the Marion County Sheriff's Office Search and Rescue and an Oregon State Police tracking canine responded to&amp;nbsp;assist&amp;nbsp;with the search. Shortly before noon, the canine&amp;nbsp;located&amp;nbsp;Hisako in Mill Creek, approximately 200 yards from her family's apartment.&lt;/span&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;The Marion County District Attorney&rsquo;s Office was notified, and a Marion County Medical Examiner responded to the scene.&amp;nbsp;At this time, there is no criminal investigation.&lt;/span&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW221965972 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
