     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Rob Stuart, President/Chief Executive Officer&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Jennifer Anderson-Kapke, Senior Vice President/Chief Compliance Officer&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Jason Buchanan, Senior Vice President/Chief Credit Officer&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Stephen Cantrell, Senior Vice President/Chief Risk Officer&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Tim Clevenger, Senior Vice President/Chief Marketing Officer&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
